<template>
  <section class="settings-view"><header><p>SETTINGS</p><h1>把纪念册变成我们的样子</h1></header><div class="settings-grid"><section class="settings-card"><div class="card-title"><span class="material-symbols-outlined">favorite</span><div><h2>关系信息</h2><p>用于计算相恋天数和页面称呼</p></div></div><label>在一起的第一天<input v-model="startDate" type="date"></label><label>对方名字<input v-model.trim="partnerName" maxlength="16" placeholder="输入昵称"></label><button class="save-settings" type="button" @click="saveRelationship">保存关系信息</button></section><section class="settings-card anniversaries"><div class="card-title"><span class="material-symbols-outlined">event</span><div><h2>自定义纪念日</h2><p>每年都会自动计算下一次日期</p></div><button type="button" @click="addAnniversary"><span class="material-symbols-outlined">add</span>添加</button></div><div class="anniversary-editor"><div v-for="item in anniversaryDrafts" :key="item.id"><input v-model.trim="item.name" aria-label="纪念日名称" placeholder="纪念日名称"><input v-model="item.date" aria-label="纪念日日期" type="date"><button type="button" aria-label="删除纪念日" @click="removeAnniversary(item.id)"><span class="material-symbols-outlined">delete</span></button></div></div><button class="save-settings" type="button" @click="saveAnniversaries">保存纪念日</button></section><section class="settings-card data-card"><div class="card-title"><span class="material-symbols-outlined">database</span><div><h2>数据管理</h2><p>导出备份，或从备份恢复记录</p></div></div><div class="data-actions"><button type="button" @click="$emit('export')"><span class="material-symbols-outlined">download</span><span><b>导出 JSON</b><small>下载全部记录与设置</small></span></button><label><input type="file" accept="application/json" @change="handleImport"><span class="material-symbols-outlined">upload</span><span><b>导入 JSON</b><small>从备份文件恢复</small></span></label><button class="danger" type="button" @click="confirmClear"><span class="material-symbols-outlined">delete_forever</span><span><b>清空所有记录</b><small>此操作无法撤销</small></span></button></div></section></div></section>
</template>
<script setup lang="ts">
import { ref, watch } from 'vue'
import type { Anniversary, RelationshipInfo } from '../types/records'
const props = defineProps<{ relationship: RelationshipInfo }>()
const emit = defineEmits<{ relationship: [startDate: string, partnerName: string]; anniversaries: [items: Anniversary[]]; export: []; import: [file: File]; clear: [] }>()
const startDate = ref(props.relationship.startDate)
const partnerName = ref(props.relationship.partnerName)
// props 来自 Vue 响应式对象，不能直接 structuredClone；显式复制字段可避免 DataCloneError。
const anniversaryDrafts = ref<Anniversary[]>(props.relationship.anniversaries.map((item) => ({ ...item })))
watch(() => props.relationship, (relationship) => {
  startDate.value = relationship.startDate
  partnerName.value = relationship.partnerName
  anniversaryDrafts.value = relationship.anniversaries.map((item) => ({ ...item }))
}, { deep: true })
function saveRelationship(): void { emit('relationship', startDate.value, partnerName.value) }
function addAnniversary(): void { anniversaryDrafts.value.push({ id: crypto.randomUUID(), name: '', date: new Date().toISOString().slice(0, 10) }) }
function removeAnniversary(id: string): void { anniversaryDrafts.value = anniversaryDrafts.value.filter((item) => item.id !== id) }
function saveAnniversaries(): void { emit('anniversaries', anniversaryDrafts.value.filter((item) => item.name && item.date).map((item) => ({ ...item }))) }
function handleImport(event: Event): void { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (file) emit('import', file); input.value = '' }
function confirmClear(): void { if (window.confirm('确定清空所有恋爱记录吗？建议先导出备份。此操作无法撤销。') && window.confirm('再次确认：真的要清空全部记录吗？')) emit('clear') }
</script>
<style scoped>
