9px;color:#7d6968;background:#fdf9f7;cursor:pointer;text-align:left}.data-actions>label>input{position:absolute;opacity:0;pointer-events:none}.data-actions>.danger{color:#cf5665;border-color:#f3d6d8;background:#fff4f4}.data-actions .material-symbols-outlined{font-size:18px}.data-actions span:last-child{display:grid}.data-actions b{font-size:9px}.data-actions small{margin-top:2px;color:#ad9a97;font-size:7px}.notice{position:fixed;right:28px;bottom:55px;display:flex;align-items:center;gap:6px;padding:9px 12px;border-radius:999px;color:#fff;background:#4e3b3d;box-shadow:0 10px 28px rgba(53,34,36,.2);font-size:9px}.notice .material-symbols-outlined{font-size:15px}.toast-enter-active,.toast-leave-active{transition:.2s}.toast-enter-from,.toast-leave-to{opacity:0;transform:translateY(8px)}
.settings-view>header p{font-size:10px}.card-title p{font-size:10px}.card-title>button{font-size:10px}.settings-card>label{font-size:11px}.settings-card input{font-size:11px}.save-settings{font-size:11px}.data-actions small{font-size:9px}.data-actions b{font-size:11px}.notice{font-size:11px}
</style>
